'use strict';

/**
 * Generated by `aid infra gen`. Do not edit: the next run refuses to overwrite a
 * hand-edited file, and the construct carries no project-specific fact to keep.
 *
 * The AWS CDK spelling of `infra/generated/modules/gateway`: one AgentCore Gateway per
 * `gateways` entry, and one `Mcp` target per tool that entry federates. It reads the same
 * context document the module reads, so the two backends cannot drift.
 *
 * The execution role is the construct's own default, which trusts
 * `bedrock-agentcore.amazonaws.com`; only the module spells a role out, because a
 * Terraform provider resource has no default. Nothing here grants a runtime
 * `InvokeGateway`: `aid infra gen` refuses the CDK backend for a plan that declares one,
 * so this construct never sees the role that would need it.
 */

const agentcore = require('aws-cdk-lib/aws-bedrockagentcore');
const cdk = require('aws-cdk-lib');
const s3 = require('aws-cdk-lib/aws-s3');

// A gateway name caps at 48 characters and a target name at 100, both over a smaller
// alphabet than a spec id: letters, digits and single separators. Scanning once keeps
// caller input away from a regular expression.
function slug(value) {
  const source = String(value);
  let out = '';
  let separator = true;
  for (let index = 0; index < source.length; index += 1) {
    const code = source.charCodeAt(index);
    const digit = code >= 48 && code <= 57;
    const upper = code >= 65 && code <= 90;
    const lower = code >= 97 && code <= 122;
    if (digit || upper || lower) {
      out += source.charAt(index).toLowerCase();
      separator = false;
    } else if (!separator) {
      out += '-';
      separator = true;
    }
  }
  while (out.endsWith('-')) out = out.slice(0, -1);
  return out;
}

// A name that ends on a separator after truncation is still legal, but two names would
// then collide on the separator; trimming keeps the suffix adjacent to the name.
function limited(value, length) {
  let out = value.slice(0, length);
  while (out.endsWith('-')) out = out.slice(0, -1);
  return out;
}

// `s3://bucket/key` splits once here rather than at each place the schema needs it. The
// spec states the whole URI as one string, and the construct wants the two halves.
function sourceOf(uri) {
  const withoutScheme = uri.indexOf('s3://') === 0 ? uri.slice(5) : uri;
  const slash = withoutScheme.indexOf('/');
  return slash === -1
    ? { bucket: withoutScheme, key: '' }
    : { bucket: withoutScheme.slice(0, slash), key: withoutScheme.slice(slash + 1) };
}

function applyTags(resource, inputs) {
  for (const key of Object.keys(inputs.tags || {})) {
    cdk.Tags.of(resource).add(key, inputs.tags[key]);
  }
}

// The construct defaults to a Cognito authorizer, and this spec exposes neither Cognito
// nor an unauthenticated gateway, so one of its two kinds is always passed.
function authorizerOf(authorizer) {
  if (authorizer.kind === 'jwt') {
    return new agentcore.CustomJwtAuthorizer({
      discoveryUrl: authorizer.discoveryUrl,
      allowedAudience: authorizer.audience,
    });
  }
  return new agentcore.IamAuthorizer();
}

// Both target kinds are one MCP target in the API, so the branches differ only in the
// configuration they carry. The schema is forwarded as the spec states it: the module does
// not validate a payload either, and validating it here alone would let one backend accept
// a document the other rejects.
function targetConfigurationOf(scope, id, target) {
  if (target.kind === 'mcpServer') {
    return agentcore.McpServerTargetConfiguration.create(target.mcpServer.endpoint);
  }
  const schema = target.openApiSchema;
  if (schema.inline !== undefined) {
    return agentcore.OpenApiTargetConfiguration.create(
      agentcore.ApiSchema.fromInline(schema.inline),
      false,
    );
  }
  const source = sourceOf(schema.uri);
  return agentcore.OpenApiTargetConfiguration.create(
    agentcore.ApiSchema.fromS3File(
      s3.Bucket.fromBucketName(scope, id + 'Bucket', source.bucket),
      source.key,
      schema.bucketOwnerAccountId,
    ),
    false,
  );
}

/**
 * Adds one gateway per `gateways` entry and returns the URL and ARN of each, keyed by the
 * spec id, so a stack can hand the URL to whatever reaches the federated tools.
 *
 * Neither target kind carries a credential provider configuration. The construct applies no
 * default for `openApiSchema` or `mcpServer` and leaves the key out of the template, which
 * is what the module does too. An OpenAPI backend that needs auth wants an API key or OAuth
 * provider that 0.24 has no field for, so it is a stated limitation rather than a default.
 */
function addGateway(scope, context, inputs) {
  const created = {};
  const gateways = context.gateways || {};

  for (const id of Object.keys(gateways)) {
    const declared = gateways[id];
    const gateway = new agentcore.Gateway(scope, id + 'Gateway', {
      gatewayName: limited(
        slug(context.project.namespace + '-' + context.project.name + '-' + id),
        48,
      ),
      description: declared.description === undefined ? undefined : declared.description,
      authorizerConfiguration: authorizerOf(declared.authorizer),
    });
    applyTags(gateway, inputs);

    for (const target of declared.targets) {
      const resource = new agentcore.GatewayTarget(scope, id + 'Target' + target.name, {
        gateway: gateway,
        gatewayTargetName: limited(slug(id + '-' + target.name), 100),
        description: target.description === undefined ? undefined : target.description,
        targetConfiguration: targetConfigurationOf(scope, id + target.name, target),
      });
      applyTags(resource, inputs);
    }

    new cdk.CfnOutput(scope, id + 'GatewayUrl', {
      description: 'The MCP endpoint the federated tools are reached through.',
      value: gateway.gatewayUrl,
    });
    new cdk.CfnOutput(scope, id + 'GatewayArn', {
      description: 'The gateway `InvokeGateway` is granted on.',
      value: gateway.gatewayArn,
    });

    created[id] = { url: gateway.gatewayUrl, arn: gateway.gatewayArn };
  }

  return created;
}

module.exports = { addGateway: addGateway };
